// AI show notes for the Runway Songs ticker: atmosphere, palette, silhouettes and materials of a show, written by
// Gemini from Google Search results and kept only with the pages it cites. Generated by scripts/show-notes.ts and
// stored in product_cache (a key/value table) under SHOW_NOTES_PREFIX; the page only reads them.

import { z } from 'zod';
import { canonicalUrl, type CitedSource } from './runway-song-candidates';

export type Show = { house: string; season: string; year: number };
export type ShowNotes = {
  summary: string;
  atmosphere: string | null;
  palette: string[];
  silhouettes: string[];
  materials: string[];
  details: string[];
  sources: { url: string; title: string | null }[];
  model: string;
  generatedAt: string;
};

export const SHOW_NOTES_PREFIX = 'show-notes|v1|';
const slug = (value: string) => value.normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
/** One key per show, whichever song or source names it. */
export const showKey = ({ house, season, year }: Show) => `${SHOW_NOTES_PREFIX}${slug(house)}|${slug(season)}|${year}`;
const showName = ({ house, season, year }: Show) => `${house} ${season} ${year}`;

// Prose first: Gemini searches and grounds prose reliably, but tends to answer a JSON request from memory.
export const showNotesResearchPrompt = (show: Show) => `Use Google Search to research the ${JSON.stringify(showName(show))} runway show.
Describe what reviews, the house's show notes and other reporting say about: the atmosphere (venue, set, lighting, mood, casting, soundtrack feel); the colour palette; the key silhouettes; the main materials and textures; and two or three other notable details (styling, accessories, the finale, references).
Report only what sources state about this specific show and season; say so when something isn't reported. Do not describe other seasons.`;

export const showNotesJsonPrompt = (show: Show, report: string, sources: { number: number; url: string }[]) => `Below is a research report on the ${JSON.stringify(showName(show))} runway show. Each [n] marks a passage supported by numbered source n.
Turn it into short notes for a scrolling ticker. Use only what the report states; leave a list empty rather than guess.
Return only JSON: {"summary":"one sentence, at most 25 words","atmosphere":"one sentence, at most 30 words, or null","palette":["up to 6 colour names"],"silhouettes":["up to 5 short phrases"],"materials":["up to 5 short phrases"],"details":["up to 3 short phrases"],"sources":["https://... copied exactly from the source list: the sources these notes draw on"]}.
Return {"summary":null} if the report doesn't describe this show.

Report:
${report}

Sources:
${sources.map(source => `[${source.number}] ${source.url}`).join('\n')}`;

const phrase = (max: number) => z.string().trim().min(1).max(max);
const list = (max: number, length: number) => z.array(phrase(length)).max(max * 2).transform(items => [...new Set(items)].slice(0, max));
const notesSchema = z.object({
  summary: phrase(240),
  atmosphere: phrase(300).nullish().transform(value => value ?? null),
  palette: list(6, 40).default([]),
  silhouettes: list(5, 80).default([]),
  materials: list(5, 80).default([]),
  details: list(3, 120).default([]),
  sources: z.array(z.string()).default([]),
});

const host = (url: string) => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return null; } };

/** Gemini's notes, kept only when they cite at least one page Google Search returned; links become those cited pages. */
export function readShowNotes(payload: unknown, cited: CitedSource[], model: string, generatedAt: string): ShowNotes | null {
  const parsed = notesSchema.safeParse(payload);
  if (!parsed.success) return null;
  const byKey = new Map(cited.flatMap(source => {
    const key = canonicalUrl(source.url);
    return key && source.url.startsWith('https://') ? [[key, source.url] as const] : [];
  }));
  const urls = [...new Set(parsed.data.sources.flatMap(url => {
    const match = byKey.get(canonicalUrl(url) ?? '');
    return match ? [match] : [];
  }))].slice(0, 5);
  if (!urls.length) return null;
  const { sources: _, ...notes } = parsed.data;
  return { ...notes, sources: urls.map(url => ({ url, title: host(url) })), model, generatedAt };
}

const storedSchema = notesSchema.omit({ sources: true }).extend({
  sources: z.array(z.object({ url: z.string().url().startsWith('https://'), title: z.string().nullable() })).min(1),
  model: z.string(),
  generatedAt: z.string(),
});

/** Notes read back from storage, or null when the row isn't (or is no longer) a valid set of notes. */
export function readStoredShowNotes(value: unknown): ShowNotes | null {
  const parsed = storedSchema.safeParse(value);
  return parsed.success ? parsed.data : null;
}

/** The ticker's run of labelled items, in reading order, skipping anything the sources didn't report. */
export function tickerItems(notes: ShowNotes): { label: string; text: string }[] {
  const joined = (items: string[]) => items.join(' · ');
  return [
    { label: 'The show', text: notes.summary },
    { label: 'Atmosphere', text: notes.atmosphere ?? '' },
    { label: 'Palette', text: joined(notes.palette) },
    { label: 'Silhouettes', text: joined(notes.silhouettes) },
    { label: 'Materials', text: joined(notes.materials) },
    { label: 'Details', text: joined(notes.details) },
    { label: 'AI notes', text: `Gemini, from ${joined(notes.sources.map(source => source.title ?? source.url))}` },
  ].filter(item => item.text);
}
